/// <summary>
/// Support opening document by document id instead of URL
/// </summary>
[ExtensionOf(classStr(DocuAction))]
final class AVADAIDocuAction_cls_Extension
{
}

Method.Source:
/// <summary>
/// Set form configuration.
/// </summary>
/// <param name = "DocuRef">Docuref table</param>
/// <returns>A <c>DocuAction</c> object.</returns>
static DocuAction newDocuRef(DocuRef _docuRef)
{
    DocuAction docuAction = next newDocuRef(_docuRef);

    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {
        if (_docuRef.AVADAIDocumentId && docuAction && classIdGet(docuAction) == classNum(DocuActionURL))
        {
            AVADAIParameters parameters = AVADAIParameters::find();
            if (parameters.Enabled == NoYes::Yes)
            {
                AVADAIServer dmsServer = AVADAIServer::findServer(parameters.ServerId);
                if (dmsServer && dmsServer.LinkOpenType == AVADAILinkOpenType::DocumentId)
                {
                    docuAction = new AVADAIDocuActionURLArchive();
                    docuAction.setDocuType(_docuRef.docuType().TypeId);
                }
            }
        }
    }

    return docuAction;
}
